import axios from 'axios';

// Настройка базового URL - замените на ваш порт
const API_BASE_URL = 'http://localhost:5128/api'; // Ваш порт из launchSettings.json

const apiClient = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  }
});

// Перехватчик для обработки ошибок
apiClient.interceptors.response.use(
  response => response,
  error => {
    console.error('API Error:', error.response?.data || error.message);
    
    if (error.response?.status === 400 && error.response?.data?.errors) {
      const errorMessages = [];
      const errors = error.response.data.errors;
      
      for (const key in errors) {
        if (Array.isArray(errors[key])) {
          errorMessages.push(...errors[key]);
        } else if (typeof errors[key] === 'string') {
          errorMessages.push(errors[key]);
        }
      }
      
      error.displayMessage = errorMessages.join('; ') || 'Ошибка валидации данных';
    } else {
      error.displayMessage = error.response?.data?.title || 
                            error.response?.data?.message || 
                            error.message || 
                            'Произошла ошибка при выполнении запроса';
    }
    
    return Promise.reject(error);
  }
);

// ============ УПРАЖНЕНИЯ (Exercises) ============
export const exerciseApi = {
  getAll() {
    return apiClient.get('/exercises');
  },
  
  getById(id) {
    return apiClient.get(`/exercises/${id}`);
  },
  
  create(data) {
    return apiClient.post('/exercises', data);
  },
  
  update(id, data) {
    return apiClient.put(`/exercises/${id}`, data);
  },
  
  delete(id) {
    return apiClient.delete(`/exercises/${id}`);
