  getActive() {
    return apiClient.get('/exercises/active');
  }
};

// ============ ПРОГРАММЫ (Programs) - НОВЫЙ БЛОК ============
export const programApi = {
  // GET /api/programs - получить все программы
  getAll() {
    return apiClient.get('/programs');
  },
  
  // GET /api/programs/{id} - получить программу по ID
  getById(id) {
    return apiClient.get(`/programs/${id}`);
  },
  
  // POST /api/programs - создать новую программу
  create(data) {
    return apiClient.post('/programs', data);
  },
  
  // PUT /api/programs/{id} - обновить программу
  update(id, data) {
    return apiClient.put(`/programs/${id}`, data);
  },
  
  // DELETE /api/programs/{id} - удалить программу
  delete(id) {
    return apiClient.delete(`/programs/${id}`);
  },
  
  // GET /api/programs/active - получить только активные программы
  getActive() {
    return apiClient.get('/programs/active');
  },
  
  // GET /api/programs/{id}/exercises - получить программу с упражнениями
  getWithExercises(id) {
    return apiClient.get(`/programs/${id}/exercises`);
  }
};

// ============ АКТИВНОСТИ (Activities) ============
export const activityApi = {
  getAll() {
    return apiClient.get('/activities');
  },
  
  getById(id) {
    return apiClient.get(`/activities/${id}`);
  },
  
  create(data) {
    return apiClient.post('/activities', data);
  },
  
  update(id, data) {
    return apiClient.put(`/activities/${id}`, data);
  },
  
  delete(id) {
    return apiClient.delete(`/activities/${id}`);
  },
  
  getByDate(date) {
    return apiClient.get(`/activities/by-date?date=${date}`);
  },
  
  getAllWithDetails() {
    return apiClient.get('/activities/details');
  }
};

// ============ ПРОГРАММЫ-УПРАЖНЕНИЯ (ProgramsExercises) ============
export const programExerciseApi = {
  getById(programId, exerciseId) {
    return apiClient.get(`/programsexercises/${programId}/${exerciseId}`);
  },
  
  create(data) {
    return apiClient.post('/programsexercises', data);
  },
  
  update(programId, exerciseId, data) {
    return apiClient.put(`/programsexercises/${programId}/${exerciseId}`, data);
  },
  
  delete(programId, exerciseId) {
    return apiClient.delete(`/programsexercises/${programId}/${exerciseId}`);
  },
  
  // Получить все упражнения для программы
  getByProgramId(programId) {
